class Cat extends StatelessWidget{final String cat;final List props;final String gt,gc;Cat({required this.cat,required this.props,required this.gt,required this.gc});@override Widget build(BuildContext c){var f=props.where((e)=>e['cat']==cat).toList();return Scaffold(appBar:AppBar(title:Text(cat),backgroundColor:Color(0xFF2E7D32)),body:f.isEmpty?Center(child:Text('Wala pay $cat - Ikaw una mag-post!')):ListView.builder(itemCount:f.length,itemBuilder:(c,i){var p=f[i];return Card(margin:EdgeInsets.all(10),child:Column(children:[Image.network(p['img'],height:180,width:double.infinity,fit:BoxFit.cover),ListTile(title:Text(p['title']),subtitle:Text('₱${p['price']}')),Row(children:[Expanded(child:OutlinedButton.icon(icon:Icon(Icons.chat),label:Text('Chat'),onPressed:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>Chat(owner:p['owner'],title:p['title']))))),Expanded(child:ElevatedButton(onPressed:()=>showModalBottomSheet(context:c,builder:(_)=>Pay(price:p['price'],com:(p['price']*0.15).toInt(),gt:gt,gc:gc)),child:Text('Book')))])]));}));}}
class Chat extends StatefulWidget{final String owner,title;Chat({required this.owner,required this.title});@override State<Chat> createState()=>_ChatS();}
class _ChatS extends State<Chat>{List<String> msgs=[];var ctrl=TextEditingController();@override void initState(){super.initState();msgs=['Hi ${widget.owner}, available pa ${widget.title}?','Yes boss! Available kaayo - GCash/GoTyme ta!'];}@override Widget build(BuildContext c){return Scaffold(appBar:AppBar(title:Text('Chat ${widget.owner} - TINUOD NA!'),backgroundColor:Color(0xFF2E7D32)),body:Column(children:[Expanded(child:ListView.builder(itemCount:msgs.length,itemBuilder:(c,i)=>Align(alignment:i%2==0?Alignment.centerRight:Alignment.centerLeft,child:Container(margin:EdgeInsets.all(8),padding:EdgeInsets.all(12),decoration:BoxDecoration(color:i%2==0?Color(0xFF2E7D32):Colors.grey.shade300,borderRadius:BorderRadius.circular(15)),child:Text(msgs[i],style:TextStyle(color:i%2==0?Colors.white:Colors.black)))))),Padding(padding:EdgeInsets.all(10),child:Row(children:[Expanded(child:TextField(controller:ctrl,decoration:InputDecoration(hintText:'Maka-chat tinuod! Type...',border:OutlineInputBorder(borderRadius:BorderRadius.circular(20))))),SizedBox(width:8),CircleAvatar(backgroundColor:Color(0xFF2E7D32),child:IconButton(icon:Icon(Icons.send,color:Colors.white),onPressed:(){if(ctrl.text.isNotEmpty){setState(()=>msgs.add(ctrl.text));ctrl.clear();Future.delayed(Duration(seconds:1),()=>setState(()=>msgs.add('Copy boss! Mo-reply ko - ${widget.owner} - GCash ta ₱?')));}}))]))]));}}
class Post extends StatefulWidget{final Function(Map<String,dynamic>) onAdd;Post({required this.onAdd});@override State<Post> createState()=>_PostS();}
class _PostS extends State<Post>{var t=TextEditingController();var p=TextEditingController();var img=TextEditingController(text:'https://images.unsplash.com/photo-1522708323590-d24dbb6b0267?w=800');String cat='House Rent';List<String> samples=['https://images.unsplash.com/photo-1522708323590-d24dbb6b0267?w=800','https://images.unsplash.com/photo-1560448204-603b3fc33ddc?w=800','https://images.unsplash.com/photo-1564013799919-ab600027ffc6?w=800'];@override Widget build(BuildContext c){return Scaffold(appBar:AppBar(title:Text('MAG POST + PICTURE - WORKING!')),body:Padding(padding:EdgeInsets.all(15),child:ListView(children:[Text('PILIA PICTURE - TINUOD NA MAKA-POST!',style:TextStyle(fontWeight:FontWeight.bold)),SizedBox(height:10),SizedBox(height:120,child:ListView.builder(scrollDirection:Axis.horizontal,itemCount:samples.length,itemBuilder:(c,i)=>InkWell(onTap:()=>setState(()=>img.text=samples[i]),child:Container(margin:EdgeInsets.all(5),width:120,decoration:BoxDecoration(border:Border.all(color:img.text==samples[i]?Colors.orange:Colors.grey,width:3),borderRadius:BorderRadius.circular(10)),child:ClipRRect(borderRadius:BorderRadius.circular(10),child:Image.network(samples[i],fit:BoxFit.cover)))))),TextField(controller:img,decoration:InputDecoration(labelText:'Picture Link - Paste diri or Pilia sa taas',border:OutlineInputBorder())),SizedBox(height:10),Image.network(img.text,height:150,fit:BoxFit.cover,errorBuilder:(c,e,s)=>Container(height:150,color:Colors.grey,child:Icon(Icons.image))),DropdownButton<String>(value:cat,isExpanded:true,items:['Airbnb','House Rent','House Sale','Lot Rent','Lot Sale','Rent Car','Food','Services'].map((e)=>DropdownMenuItem(value:e,child:Text(e))).toList(),onChanged:(v)=>setState(()=>cat=v!)),TextField(controller:t,decoration:InputDecoration(labelText:'Title',border:OutlineInputBorder())),SizedBox(height:8),TextField(controller:p,decoration:InputDecoration(labelText:'Price',border:OutlineInputBorder()),keyboardType:TextInputType.number),SizedBox(height:15),ElevatedButton(style:ElevatedButton.styleFrom(backgroundColor:Colors.orange,padding:EdgeInsets.all(15)),onPressed:(){if(t.text.isEmpty){ScaffoldMessenger.of(c).showSnackBar(SnackBar(content:Text('Butangi Title!')));return;}widget.onAdd({'title':t.text,'price':int.tryParse(p.text)??15000,'loc':'Davao','cat':cat,'owner':'Ikaw','img':img.text});Navigator.pop(c);ScaffoldMessenger.of(c).showSnackBar(SnackBar(content:Text('✅ NA-POST NA UBAN ANG PICTURE!')));},child:Text('I-POST NA!',style:TextStyle(fontSize:16)))])));}}
class Pay extends StatelessWidget{final int price,com;final String gt,gc;Pay({required this.price,required this.com,required this.gt,required this.gc});@override Widget build(BuildContext c){return Container(padding:EdgeInsets.all(20),child:Column(mainAxisSize:MainAxisSize.min,children:[Text('Bayad ₱$price Commission ₱$com AUTO $gt/$gc',style:TextStyle(fontWeight:FontWeight.bold)),Wrap(children:['GCash','Maya','GoTyme','BPI','BDO','Metrobank'].map((e)=>Chip(label:Text(e))).toList()),SizedBox(height:10),SizedBox(width:double.infinity,child:ElevatedButton(style:ElevatedButton.styleFrom(backgroundColor:Colors.orange),onPressed:(){Navigator.pop(c);showDialog(context:c,builder:(_)=>AlertDialog(title:Text('✅ BAYAD NA!'),content:Text('Via GCash/GoTyme ₱$price\nCommission ₱$com AUTO sa $gt')));},child:Text('BAYARAN ₱$price')))]));}}
